INSERT INTO `asb_drama_script` VALUES (/*command_id*/62020, /*drama_id*/62, /*command_type*/11, /*param_01*/'1', /*param_02*/'那三位实在是太可爱又精致了，\n我……真的……\n感觉整个人都晕乎乎的……', /*param_03*/'10', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'0');
