INSERT INTO `asb_drama_script` VALUES (/*command_id*/72013, /*drama_id*/72, /*command_type*/11, /*param_01*/'1', /*param_02*/'碧小姐好像是一个非常腼腆的人。\n不过，好像有句话是这样说的。\n“有共同话题的人\n会更容易打成一片”。', /*param_03*/'10', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'0');
