INSERT INTO `asb_drama_script` VALUES (/*command_id*/72015, /*drama_id*/72, /*command_type*/3, /*param_01*/'1', /*param_02*/'clear_kohon_talk_surprise', /*param_03*/'1', /*param_04*/'', /*param_05*/'', /*param_06*/'0.2', /*param_07*/'', /*param_08*/'');
INSERT INTO `asb_drama_script` VALUES (/*command_id*/72016, /*drama_id*/72, /*command_type*/21, /*param_01*/'vo_asb', /*param_02*/'vo_asb_0722', /*param_03*/'0', /*param_04*/'0', /*param_05*/'', /*param_06*/'', /*param_07*/'', /*param_08*/'');
INSERT INTO `asb_drama_script` VALUES (/*command_id*/72017, /*drama_id*/72, /*command_type*/11, /*param_01*/'1', /*param_02*/'凭直觉判断，我觉得是有的。\n虽然比不上碧小姐那么了解，\n但我也很喜欢花草。\n我应该……可以和她成为好朋友。', /*param_03*/'10', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'0');
INSERT INTO `asb_drama_script` VALUES (/*command_id*/72018, /*drama_id*/72, /*command_type*/91, /*param_01*/'0', /*param_02*/'', /*param_03*/'0', /*param_04*/'0', /*param_05*/'', /*param_06*/'', /*param_07*/'', /*param_08*/'');
INSERT INTO `asb_drama_script` VALUES (/*command_id*/72019, /*drama_id*/72, /*command_type*/3, /*param_01*/'1', /*param_02*/'clear_talk2_noShy', /*param_03*/'1', /*param_04*/'', /*param_05*/'', /*param_06*/'0.2', /*param_07*/'', /*param_08*/'');
INSERT INTO `asb_drama_script` VALUES (/*command_id*/72020, /*drama_id*/72, /*command_type*/21, /*param_01*/'vo_asb', /*param_02*/'vo_asb_0723', /*param_03*/'0', /*param_04*/'0', /*param_05*/'', /*param_06*/'', /*param_07*/'', /*param_08*/'');
INSERT INTO `asb_drama_script` VALUES (/*command_id*/72021, /*drama_id*/72, /*command_type*/11, /*param_01*/'1', /*param_02*/'所以，\n我鼓起勇气说了出来！\n问她……愿不愿意和我做朋友。', /*param_03*/'10', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'0');
INSERT INTO `asb_drama_script` VALUES (/*command_id*/72022, /*drama_id*/72, /*command_type*/91, /*param_01*/'0', /*param_02*/'', /*param_03*/'0', /*param_04*/'0', /*param_05*/'', /*param_06*/'', /*param_07*/'', /*param_08*/'');
