INSERT INTO `asb_drama_script` VALUES (/*command_id*/72024, /*drama_id*/72, /*command_type*/21, /*param_01*/'vo_asb', /*param_02*/'vo_asb_0724', /*param_03*/'0', /*param_04*/'0', /*param_05*/'', /*param_06*/'', /*param_07*/'', /*param_08*/'');
INSERT INTO `asb_drama_script` VALUES (/*command_id*/72025, /*drama_id*/72, /*command_type*/11, /*param_01*/'1', /*param_02*/'然后，\n碧小姐的脸涨得通红，\n对着我用力点了点头。\n她应该是在想“太好了！”吧。', /*param_03*/'10', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'0');
INSERT INTO `asb_drama_script` VALUES (/*command_id*/72026, /*drama_id*/72, /*command_type*/91, /*param_01*/'0', /*param_02*/'', /*param_03*/'0', /*param_04*/'0', /*param_05*/'', /*param_06*/'', /*param_07*/'', /*param_08*/'');
INSERT INTO `asb_drama_script` VALUES (/*command_id*/72027, /*drama_id*/72, /*command_type*/3, /*param_01*/'1', /*param_02*/'clear_talk2_nervous', /*param_03*/'1', /*param_04*/'', /*param_05*/'', /*param_06*/'0.2', /*param_07*/'', /*param_08*/'');
