INSERT INTO `asb_drama_script` VALUES (/*command_id*/72029, /*drama_id*/72, /*command_type*/11, /*param_01*/'1', /*param_02*/'……不过在那之后，\n她又说自己需要做心理准备。\n她说要做好心理准备，\n或许要花上三百年……', /*param_03*/'10', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'0');
