INSERT INTO `asb_drama_script` VALUES (/*command_id*/72033, /*drama_id*/72, /*command_type*/11, /*param_01*/'1', /*param_02*/'这也不奇怪吧……\n的确是进展太快了……', /*param_03*/'10', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'0');
