INSERT INTO `asb_drama_script` VALUES (/*command_id*/82013, /*drama_id*/82, /*command_type*/11, /*param_01*/'1', /*param_02*/'那时候，我接受了\n别人的邀约。\n据美里小姐所说，我具备当保育员的\n“与生俱来的才能”。', /*param_03*/'10', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'0');
