INSERT INTO `asb_drama_script` VALUES (/*command_id*/82015, /*drama_id*/82, /*command_type*/3, /*param_01*/'1', /*param_02*/'sad_talk_surprise', /*param_03*/'1', /*param_04*/'', /*param_05*/'', /*param_06*/'0.2', /*param_07*/'', /*param_08*/'');
