INSERT INTO `asb_drama_script` VALUES (/*command_id*/82017, /*drama_id*/82, /*command_type*/11, /*param_01*/'1', /*param_02*/'先不论小孩子，\n我知道自己很受动物喜爱……\n我也有自知之明，\n明白自己不适合做冒险者这份工作……', /*param_03*/'10', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'0');
