INSERT INTO `asb_drama_script` VALUES (/*command_id*/82021, /*drama_id*/82, /*command_type*/11, /*param_01*/'1', /*param_02*/'但是……能够跨越适应能力这个难关，\n在自己的道路上勇往直前，才是冒险者。\n一旦做出决定，\n就不能屈服！', /*param_03*/'10', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'0');
