INSERT INTO `asb_drama_script` VALUES (/*command_id*/112012, /*drama_id*/112, /*command_type*/11, /*param_01*/'1', /*param_02*/'深月小姐\n端上来的自制茶水\n散发着一种奇异的香味。', /*param_03*/'10', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'0');
