INSERT INTO `asb_drama_script` VALUES (/*command_id*/112016, /*drama_id*/112, /*command_type*/11, /*param_01*/'1', /*param_02*/'只是闻一闻，就觉得全身\n轻飘飘的，还会发热。\n按照深月小姐的说法，\n那种茶好像有滋补的功效。', /*param_03*/'10', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'0');
