INSERT INTO `asb_drama_script` VALUES (/*command_id*/112020, /*drama_id*/112, /*command_type*/11, /*param_01*/'1', /*param_02*/'不知道为什么，哥哥罕见地表现出了\n焦急的样子，劝我不要喝，\n最后我只是\n闻了闻香味，没有喝……', /*param_03*/'10', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'0');
