INSERT INTO `asb_drama_script` VALUES (/*command_id*/112024, /*drama_id*/112, /*command_type*/11, /*param_01*/'1', /*param_02*/'深月小姐说，\n“下次我会给你喝\n更有效的茶，\n欢迎再来哦”', /*param_03*/'10', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'0');
