INSERT INTO `asb_drama_script` VALUES (/*command_id*/112027, /*drama_id*/112, /*command_type*/11, /*param_01*/'1', /*param_02*/'既然她都这么说了，\n那我下次还想去玩。', /*param_03*/'10', /*param_04*/'1', /*param_05*/'1', /*param_06*/'0', /*param_07*/'0', /*param_08*/'0');
